import{_ as l,o as r,c as i,a2 as e}from"./chunks/framework.CnqZ57Z3.js";const b=JSON.parse('{"title":"附录 · Flutter 引擎与 Embedder 定制","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/engine-embedder.md","filePath":"appendix/engine-embedder.md","lastUpdated":1793872473000}'),a={name:"appendix/engine-embedder.md"},s={viewBox:"0 0 880 470",width:"100%",role:"img","aria-label":"Flutter framework、engine、embedder 三层结构图",style:{"max-width":"880px",display:"block",margin:"0 auto"}};function d(n,t,o,f,h,c){return r(),i("div",null,[t[1]||(t[1]=e('<h1 id="附录-·-flutter-引擎与-embedder-定制" tabindex="-1">附录 · Flutter 引擎与 Embedder 定制 <a class="header-anchor" href="#附录-·-flutter-引擎与-embedder-定制" aria-label="Permalink to &quot;附录 · Flutter 引擎与 Embedder 定制&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">本附录为架构说明，不含可运行示例</p><p>引擎构建与自定义 embedder 需要完整的 engine 源码、<code>gclient</code> 同步与各平台工具链，无法在教程仓库内以「打开即跑」的形式提供。本页只讲结构与边界，不硬凑假 demo。</p></div><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ul><li>绝大多数业务不需要改引擎。需要改引擎的信号通常只有三类：<strong>平台能力缺失</strong>、<strong>性能瓶颈在引擎内部</strong>、<strong>要把 Flutter 嵌进非标准宿主</strong>。</li><li>改引擎的真实成本不在「写 patch」，而在<strong>每次 Flutter 升级都要 rebase</strong>，以及自建产物分发与 CI。</li><li>自定义 <strong>embedder</strong> 是官方允许的路径（引擎提供 C API）；自定义 <strong>shell</strong> 不是稳定接口，等于长期维护一个引擎分支。</li><li>PlatformView 与纹理合成的复杂度集中在 <strong>embedder + raster 线程</strong>，framework 侧只负责协议与组合。</li><li>先尝试插件 / PlatformView / 外接纹理，再考虑引擎补丁；顺序反过来通常要付双倍成本。</li></ul><h2 id="一、三层边界" tabindex="-1">一、三层边界 <a class="header-anchor" href="#一、三层边界" aria-label="Permalink to &quot;一、三层边界&quot;">​</a></h2>',5)),(r(),i("svg",s,[...t[0]||(t[0]=[e('<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#5b6b7c"></path></marker></defs><rect x="20" y="16" width="840" height="112" rx="10" fill="#eef4ff" stroke="#8fb4e8"></rect><text x="36" y="40" font-family="system-ui, sans-serif" font-size="14" font-weight="700" fill="#1f3b63">Framework（Dart，你的业务与 UI 代码）</text><rect x="40" y="56" width="180" height="52" rx="6" fill="#ffffff" stroke="#8fb4e8"></rect><text x="130" y="86" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1f3b63">Widgets / Material</text><rect x="236" y="56" width="180" height="52" rx="6" fill="#ffffff" stroke="#8fb4e8"></rect><text x="326" y="86" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1f3b63">Rendering（Layer / Paint）</text><rect x="432" y="56" width="180" height="52" rx="6" fill="#ffffff" stroke="#8fb4e8"></rect><text x="522" y="86" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1f3b63">Scheduler / Gestures</text><rect x="628" y="56" width="212" height="52" rx="6" fill="#ffffff" stroke="#8fb4e8"></rect><text x="734" y="86" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1f3b63">Services（平台通道 / 纹理）</text><line x1="440" y1="128" x2="440" y2="164" stroke="#5b6b7c" stroke-width="1.5" marker-end="url(#arrow)"></line><text x="452" y="150" font-family="system-ui, sans-serif" font-size="11" fill="#5b6b7c">dart:ui（Engine 暴露给 Dart 的绑定层）</text><rect x="20" y="166" width="840" height="132" rx="10" fill="#f2fbf5" stroke="#7bbf9a"></rect><text x="36" y="190" font-family="system-ui, sans-serif" font-size="14" font-weight="700" fill="#1d4b36">Engine（C++ 核心：Shell + Runtime + Rasterizer）</text><rect x="40" y="204" width="150" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="115" y="226" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">Dart VM / AOT</text><rect x="200" y="204" width="150" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="275" y="226" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">Skia / Impeller</text><rect x="360" y="204" width="150" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="435" y="226" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">Text / Typography</text><rect x="520" y="204" width="150" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="595" y="226" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">PlatformView</text><rect x="680" y="204" width="160" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="760" y="226" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">Texture / 合成</text><rect x="40" y="248" width="380" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="230" y="270" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">UI 线程（Dart isolate）</text><rect x="430" y="248" width="190" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="525" y="270" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">Raster / GPU 线程</text><rect x="630" y="248" width="210" height="34" rx="6" fill="#ffffff" stroke="#7bbf9a"></rect><text x="735" y="270" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#1d4b36">IO 线程（解码 / 资源）</text><line x1="440" y1="300" x2="440" y2="336" stroke="#5b6b7c" stroke-width="1.5" marker-end="url(#arrow)"></line><text x="452" y="322" font-family="system-ui, sans-serif" font-size="11" fill="#5b6b7c">FlutterEngine C API：surface / vsync / input / lifecycle</text><line x1="440" y1="338" x2="440" y2="334" stroke="#5b6b7c" stroke-width="1.5" marker-end="url(#arrow)"></line><text x="12" y="322" font-family="system-ui, sans-serif" font-size="11" fill="#5b6b7c">回调 / 消息</text><rect x="20" y="340" width="840" height="112" rx="10" fill="#fff7ed" stroke="#d8a45c"></rect><text x="36" y="364" font-family="system-ui, sans-serif" font-size="14" font-weight="700" fill="#6b4310">Embedder（每个平台一份实现）</text><rect x="40" y="380" width="180" height="52" rx="6" fill="#ffffff" stroke="#d8a45c"></rect><text x="130" y="402" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#6b4310">Android（Java / C++）</text><text x="130" y="420" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#6b4310">SurfaceView / TextureView</text><rect x="236" y="380" width="180" height="52" rx="6" fill="#ffffff" stroke="#d8a45c"></rect><text x="326" y="402" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#6b4310">iOS（Objective-C / Swift）</text><text x="326" y="420" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#6b4310">FlutterViewController</text><rect x="432" y="380" width="180" height="52" rx="6" fill="#ffffff" stroke="#d8a45c"></rect><text x="522" y="402" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#6b4310">Windows / Linux / macOS</text><text x="522" y="420" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#6b4310">GL / Vulkan / Metal</text><rect x="628" y="380" width="212" height="52" rx="6" fill="#ffffff" stroke="#d8a45c"></rect><text x="734" y="402" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#6b4310">Web（浏览器即宿主）</text><text x="734" y="420" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#6b4310">CanvasKit / skwasm</text>',49)])])),t[2]||(t[2]=e(`<p>三层职责一句话概括：</p><table tabindex="0"><thead><tr><th>层</th><th>负责</th><th>不负责</th></tr></thead><tbody><tr><td>Framework</td><td>Widget、布局、绘制指令、手势、平台通道协议</td><td>线程、窗口、GPU 上下文</td></tr><tr><td>Engine</td><td>Dart 运行时、渲染后端、文本、Shell、PlatformView 合成</td><td>窗口创建、输入事件来源、应用生命周期</td></tr><tr><td>Embedder</td><td>窗口 / surface、vsync、输入、生命周期、无障碍、通道桥接</td><td>Widget 与业务语义</td></tr></tbody></table><h2 id="二、引擎构建与产物" tabindex="-1">二、引擎构建与产物 <a class="header-anchor" href="#二、引擎构建与产物" aria-label="Permalink to &quot;二、引擎构建与产物&quot;">​</a></h2><p>引擎仓库是 <code>flutter/engine</code>，framework 仓库通过 <code>bin/internal/engine.version</code> 锁定对应的引擎 commit。构建流程大致是：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gclient</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./flutter/tools/gn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runtime-mode=release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target-os=android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out/android_release_arm64</span></span></code></pre></div><p>产物形态按平台不同：</p><table tabindex="0"><thead><tr><th>平台</th><th>主要产物</th><th>说明</th></tr></thead><tbody><tr><td>Android</td><td><code>libflutter.so</code>、<code>flutter.jar</code></td><td>按 ABI 分包；release 走 AOT</td></tr><tr><td>iOS</td><td><code>Flutter.framework</code> / <code>Flutter.xcframework</code></td><td>含 arm64 与模拟器切片</td></tr><tr><td>Windows / Linux</td><td><code>flutter_engine.dll</code> / <code>libflutter_engine.so</code></td><td>桌面 embedder 链接</td></tr><tr><td>Web</td><td><code>flutter.js</code>、CanvasKit / skwasm</td><td>没有传统 embedder，浏览器负责宿主</td></tr></tbody></table><p>自编译引擎接入应用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local-engine=android_release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local-engine-src-path=/path/to/engine/src</span></span></code></pre></div><p>关键点：</p><ul><li><code>--local-engine</code> 只适合本地验证，CI 需要自建产物仓库并按版本归档；</li><li>engine 与 framework 版本必须匹配，混用会出现符号 / ABI 不兼容；</li><li>debug / profile / release 三种 runtime 模式的产物不能互换。</li></ul><h2 id="三、embedder-接口与线程模型" tabindex="-1">三、Embedder 接口与线程模型 <a class="header-anchor" href="#三、embedder-接口与线程模型" aria-label="Permalink to &quot;三、Embedder 接口与线程模型&quot;">​</a></h2><p>Embedder 通过 <code>FlutterEngineRun</code>（C API）向引擎提供：</p><ul><li><strong>渲染 surface</strong>：OpenGL / Vulkan / Metal / 软件渲染，交给 rasterizer；</li><li><strong>vsync 回调</strong>：驱动帧调度；</li><li><strong>输入</strong>：触摸、鼠标、键盘、滚轮，转成引擎事件；</li><li><strong>生命周期</strong>：pause / resume / detach，决定帧循环是否继续；</li><li><strong>平台消息</strong>：<code>FlutterPlatformMessageCallback</code> 承载 MethodChannel / BasicMessageChannel；</li><li><strong>纹理注册</strong>：外接纹理的创建、更新、销毁；</li><li><strong>无障碍桥</strong>：语义树导出。</li></ul><p>线程模型（移动端 / 桌面）：</p><table tabindex="0"><thead><tr><th>线程</th><th>职责</th><th>约束</th></tr></thead><tbody><tr><td>Platform</td><td>宿主 UI 线程、输入、通道回调</td><td>不能阻塞，否则 ANR / 掉帧</td></tr><tr><td>UI</td><td>Dart isolate，build / layout / paint 成 LayerTree</td><td>业务耗时都在这里</td></tr><tr><td>Raster</td><td>LayerTree → GPU 命令（Impeller）</td><td>受图层复杂度与 shader 编译影响</td></tr><tr><td>IO</td><td>图片解码、资源读取</td><td>不要与 raster 抢带宽</td></tr></tbody></table><p>帧管线：<code>vsync → 调度 → animate → build/layout/paint → 提交 LayerTree → raster → 上屏</code>。任何一环超预算都会掉帧。</p><p>Web 是特例：浏览器没有独立 embedder 线程模型，帧调度由 <code>requestAnimationFrame</code> 驱动，Dart 编译为 JS / Wasm 后在主线程执行（Worker 能力有限）。</p><h2 id="四、自定义-embedder-与自定义-shell-的边界" tabindex="-1">四、自定义 embedder 与自定义 shell 的边界 <a class="header-anchor" href="#四、自定义-embedder-与自定义-shell-的边界" aria-label="Permalink to &quot;四、自定义 embedder 与自定义 shell 的边界&quot;">​</a></h2><p><strong>自定义 embedder（可行）</strong>：</p><ul><li>场景：把 Flutter 嵌进游戏引擎、机顶盒、车机、自研合成器；</li><li>路径：链接引擎库，实现 <code>FlutterRendererConfig</code>、<code>FlutterTaskRunnerDescription</code>、平台消息与生命周期回调；</li><li>需要自己解决：GPU 上下文、线程调度、输入映射、字体、无障碍、剪贴板；</li><li>风险：引擎升级时 C API 有变动，需要跟着改；平台能力（相机、传感器）仍要自己做插件。</li></ul><p><strong>自定义 shell（不建议）</strong>：</p><ul><li><code>flutter::Shell</code>、<code>Engine</code>、<code>Rasterizer</code> 属于内部实现，不是稳定接口；</li><li>改 shell 等于维护引擎分支：每次上游升级都要 rebase，冲突集中在 frame pipeline；</li><li>除非你在做 Flutter 衍生运行时（如嵌入式 / 自研渲染后端），否则成本远大于收益。</li></ul><p>判断顺序：<strong>插件 → PlatformView / 外接纹理 → 自定义 embedder → 引擎补丁 → fork shell</strong>。越往后，维护成本指数上升。</p><h2 id="五、platformview-与纹理合成在引擎层的位置" tabindex="-1">五、PlatformView 与纹理合成在引擎层的位置 <a class="header-anchor" href="#五、platformview-与纹理合成在引擎层的位置" aria-label="Permalink to &quot;五、PlatformView 与纹理合成在引擎层的位置&quot;">​</a></h2><p>PlatformView 的本质是「原生视图的内容进入 Flutter 的合成树」，两条实现路径：</p><table tabindex="0"><thead><tr><th>模式</th><th>机制</th><th>成本</th></tr></thead><tbody><tr><td>Virtual Display</td><td>原生视图渲染到虚拟显示，再作为纹理上传</td><td>多一次 GPU 拷贝，刷新同步差</td></tr><tr><td>Hybrid Composition</td><td>原生视图直接嵌入视图层级，引擎负责裁剪与变换</td><td>平台差异大，滚动 / 变换时性能差</td></tr></tbody></table><p>在引擎里的位置：</p><ul><li>framework 侧：<code>PlatformViewsController</code> 负责协议、尺寸、触摸转发；</li><li>engine 侧：<code>PlatformView</code> 相关代码在 shell / embedder 之间传递纹理与元数据；</li><li>raster 线程负责把纹理作为一层合成进最终画面；</li><li>触摸事件需要从 Flutter 命中测试反向转发给原生视图。</li></ul><p>外接纹理（<code>Texture</code>）走的是另一条路：原生侧把帧写入 <code>SurfaceTexture</code> / <code>CVPixelBuffer</code>，注册为 GPU 纹理，framework 只拿 <code>textureId</code>。视频、相机、地图通常用这条路径。</p><p>工程结论：</p><ul><li>能用外接纹理就不要用 PlatformView；</li><li>PlatformView 要控制数量，避免每帧多次纹理拷贝；</li><li>需要动画 / 变换频繁的场景，优先原生侧渲染到纹理。</li></ul><h2 id="六、引擎补丁维护与版本对齐的成本" tabindex="-1">六、引擎补丁维护与版本对齐的成本 <a class="header-anchor" href="#六、引擎补丁维护与版本对齐的成本" aria-label="Permalink to &quot;六、引擎补丁维护与版本对齐的成本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成本项</th><th>具体表现</th></tr></thead><tbody><tr><td>版本对齐</td><td>framework 每次升级都更新 <code>engine.version</code>，补丁必须 rebase 到新 commit</td></tr><tr><td>冲突集中</td><td>改动常落在 frame pipeline / rasterizer，上游也在频繁改</td></tr><tr><td>产物分发</td><td>自建引擎要托管多平台多 ABI 产物，CI 时间与存储显著增加</td></tr><tr><td>验证成本</td><td>每个平台都要跑回归，golden 与性能基线要重建</td></tr><tr><td>安全响应</td><td>上游安全修复要重新移植，延迟即风险</td></tr></tbody></table><p>降低成本的实践：</p><ol><li><strong>先上游</strong>：能提 PR 就提，进入官方引擎后维护成本归零；</li><li><strong>补丁最小化</strong>：只改必要函数，不加日志、不做顺手重构；</li><li><strong>隔离</strong>：把改动收敛到独立文件 / 开关，减少 rebase 冲突；</li><li><strong>固定节奏</strong>：每个 Flutter 稳定版升级时同步 rebase，不要攒版本；</li><li><strong>可回退</strong>：保留官方引擎产物，出问题能立刻切回；</li><li><strong>CI 覆盖</strong>：至少 Android / iOS 各一台真机跑冒烟与性能基线。</li></ol><h2 id="七、常见坑" tabindex="-1">七、常见坑 <a class="header-anchor" href="#七、常见坑" aria-label="Permalink to &quot;七、常见坑&quot;">​</a></h2><ol><li><strong>以为改 framework 就能改引擎</strong>：framework 是 Dart 层，线程与合成在引擎里。</li><li><strong>engine 与 framework 版本混用</strong>：符号缺失、启动崩溃。</li><li><strong><code>--local-engine</code> 用到 CI</strong>：产物不可复现，换机器即失败。</li><li><strong>自定义 embedder 忽略生命周期</strong>：后台仍在跑帧循环，耗电且被系统杀。</li><li><strong>在 platform 线程做重活</strong>：ANR、输入卡顿。</li><li><strong>raster 线程上做同步 IO</strong>：掉帧且难以定位。</li><li><strong>PlatformView 泛滥</strong>：每帧多次纹理拷贝，滚动直接崩。</li><li><strong>把 shell 内部 API 当稳定接口</strong>：小版本升级就编译失败。</li><li><strong>补丁不做版本归档</strong>：线上崩溃无法还原到对应引擎。</li><li><strong>只测 debug</strong>：AOT 下行为与符号都不同。</li><li><strong>忽略 Web 的线程差异</strong>：把移动端经验直接套到浏览器。</li><li><strong>自建引擎不跟安全更新</strong>：上游修复长期缺失。</li></ol><h2 id="八、延伸阅读" tabindex="-1">八、延伸阅读 <a class="header-anchor" href="#八、延伸阅读" aria-label="Permalink to &quot;八、延伸阅读&quot;">​</a></h2><ul><li>Flutter 引擎仓库：<a href="https://github.com/flutter/engine" target="_blank" rel="noreferrer">https://github.com/flutter/engine</a></li><li>引擎架构总览：<a href="https://github.com/flutter/flutter/blob/main/docs/engine/README.md" target="_blank" rel="noreferrer">https://github.com/flutter/flutter/blob/main/docs/engine/README.md</a></li><li>自定义 embedder 示例（engine 仓库 <code>examples/</code>）：<a href="https://github.com/flutter/engine/tree/main/examples" target="_blank" rel="noreferrer">https://github.com/flutter/engine/tree/main/examples</a></li><li>Android 嵌入层：<a href="https://docs.flutter.dev/platform-integration/android/platform-views" target="_blank" rel="noreferrer">https://docs.flutter.dev/platform-integration/android/platform-views</a></li><li>iOS 嵌入层：<a href="https://docs.flutter.dev/platform-integration/ios/platform-views" target="_blank" rel="noreferrer">https://docs.flutter.dev/platform-integration/ios/platform-views</a></li><li>Impeller：<a href="https://docs.flutter.dev/perf/impeller" target="_blank" rel="noreferrer">https://docs.flutter.dev/perf/impeller</a></li><li>引擎版本文件：<a href="https://github.com/flutter/flutter/blob/main/bin/internal/engine.version" target="_blank" rel="noreferrer">https://github.com/flutter/flutter/blob/main/bin/internal/engine.version</a></li></ul>`,40))])}const g=l(a,[["render",d]]);export{b as __pageData,g as default};
